// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public { c = new PrivateBank(address(new Log())); }

    function testFuzz_property(uint256 deposit, uint256 amount, address actor) public {
        vm.assume(deposit <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        deposit = bound(deposit, 1 ether, 1000 ether);
        // admissible: can only withdraw an amount already in the balance
        amount = bound(amount, 1, deposit);

        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Deposit{value: deposit}();

        vm.prank(actor);
        c.CashOut(amount);

        // General rule: after a successful withdrawal of `amount`, the caller's
        // balance is exactly deposit - amount (withdrawals always decrease balances).
        assertTrue(c.balances(actor) == deposit - amount);
    }
}
